import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import api from "../api"; 

const ROLES = [
  {id:"student", label:"Student",  emoji:"🎓", placeholder:"email@example.com"},
  {id:"company", label:"Company",  emoji:"🏢", placeholder:"hr@company.com"},
  {id:"admin",   label:"Admin",    emoji:"🏛️", placeholder:"admin@stag.io"},
];

export default function Login() {
  const [role, setRole]         = useState("student");
  const [email, setEmail]       = useState(""); 
  const [password, setPassword] = useState("");
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading]   = useState(false);
  
  const navigate = useNavigate();
  const cfg = ROLES.find(r => r.id === role);

  const handleLogin = async (e) => {
    e.preventDefault();
    if (!email || !password) {
      alert("Please fill in your credentials");
      return;
    }

    setLoading(true);
    try {
      // 1. API Call for Authentication
      const response = await api.post('login/', {
        username: email, // Django expects 'username'
        password: password
      });

      // 2. Store Tokens
      localStorage.setItem('access_token', response.data.access);
      localStorage.setItem('refresh_token', response.data.refresh);

      // 3. Fetch User Profile to get the verified Role
      const userRes = await api.get('profile/');
      const userRole = userRes.data.role.toLowerCase();
      
      localStorage.setItem('userRole', userRole);

      // 4. Role-Based Navigation
      if (userRole === "student") navigate("/student/dashboard");
      else if (userRole === "company") navigate("/company/dashboard");
      else if (userRole === "admin") navigate("/admin/dashboard");

    } catch (error) {
      console.error("Login error:", error);
      const errorMsg = error.response?.data?.detail || "Invalid credentials. Please try again.";
      alert(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex bg-[#fdf9f5]">
      <div className="hidden lg:flex lg:w-[52%] bg-slate-900 flex-col justify-center px-12 relative overflow-hidden">
        <div className="absolute inset-0 opacity-40 dot-grid"/>
        <div className="relative z-10">
          <Link to="/" className="font-syne font-extrabold text-2xl text-white tracking-tight">Stag<span className="text-blue-500">.</span>io</Link>
          <h1 className="font-syne font-extrabold text-white leading-tight mt-10 text-5xl">
            Empowering your <br/> professional <span className="text-blue-400">future.</span>
          </h1>
        </div>
      </div>

      <div className="flex-1 flex flex-col justify-center items-center px-6 py-12">
        <div className="w-full max-w-md">
          <h2 className="font-syne font-extrabold text-slate-900 text-3xl mb-8">Sign In</h2>

          <div className="bg-slate-100 rounded-xl p-1 flex mb-7">
            {ROLES.map(r => (
              <button key={r.id} onClick={() => setRole(r.id)}
                className={`flex-1 flex items-center justify-center gap-1.5 py-2 rounded-lg text-sm font-medium transition-all ${role===r.id?"bg-white text-slate-900 shadow-sm":"text-slate-500"}`}>
                <span>{r.emoji}</span><span>{r.label}</span>
              </button>
            ))}
          </div>

          <form onSubmit={handleLogin} className="space-y-5">
            <input 
              type="email" 
              value={email} 
              onChange={e=>setEmail(e.target.value)} 
              placeholder={cfg.placeholder} 
              className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" 
            />
            <div className="relative">
              <input type={showPass?"text":"password"} 
                value={password}
                onChange={e=>setPassword(e.target.value)} 
                placeholder="Password" 
                className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
              />
              <button type="button" onClick={()=>setShowPass(!showPass)} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400">
                {showPass?"🙈":"👁️"}
              </button>
            </div>

            <button 
              type="submit"
              disabled={loading}
              className={`w-full bg-slate-900 text-white font-semibold py-3 rounded-xl text-sm ${loading ? 'opacity-70 cursor-not-allowed' : 'hover:bg-slate-800'}`}
            >
              {loading ? "Processing..." : "Sign In →"}
            </button>
            
            <p className="text-center text-sm text-slate-600 mt-4">
              New here? <Link to="/register" className="text-blue-600 font-bold">Create an account</Link>
            </p>
          </form>
        </div>
      </div>
    </div>
  );
}
